<script setup>
import {onMounted,ref} from 'vue'
import {ElTable,ElTableColumn,ElTag} from 'element-plus'
import {api,queryString} from '../../../shared/api.js'
import {money} from '../../../shared/demo.mjs'
import {useTask} from '../../../shared/use-task.js'
import Dialog from '../../../shared/Dialog.vue'
import Feedback from '../components/Feedback.vue'
import Pager from '../components/Pager.vue'
const emit=defineEmits(['grant'])
const {busy,error,run}=useTask(),list=ref({items:[],page:1,total:0}),keyword=ref(''),detail=ref(null),ledger=ref({items:[],page:1,total:0})
const load=async(page=1)=>list.value=await api(`/admin/users${queryString({keyword:keyword.value,page})}`)
async function open(user){await run(async()=>{const [u,l]=await Promise.all([api(`/admin/users/${user.id}`),api(`/admin/users/${user.id}/wallet/ledger`)]);detail.value=u;ledger.value=l})}
onMounted(()=>run(()=>load()))
</script>
<template><section class="panel"><Feedback :error="error"/><form class="filter-bar" @submit.prevent="run(()=>load())"><input v-model.trim="keyword" aria-label="搜索用户" placeholder="用户名 / 昵称 / 用户 ID"><button class="secondary" :disabled="busy">查询用户</button></form><ElTable :data="list.items"><ElTableColumn prop="id" label="用户 ID" width="90"/><ElTableColumn prop="username" label="用户名" min-width="140"/><ElTableColumn prop="nickname" label="昵称" min-width="130"/><ElTableColumn prop="parentId" label="上线 ID" width="100"/><ElTableColumn prop="inviteCode" label="邀请码" min-width="150"/><ElTableColumn label="产品券余额" min-width="140"><template #default="{row}">{{ money(row.balanceUnits) }} 券</template></ElTableColumn><ElTableColumn label="操作" min-width="180"><template #default="{row}"><button class="table-button" @click="open(row)">用户详情</button><button class="table-button" @click="emit('grant',row)">发放产品券</button></template></ElTableColumn></ElTable><Pager :page="list.page" :total="list.total" :disabled="busy" @change="page=>run(()=>load(page))"/></section><Dialog v-if="detail" :title="`${detail.nickname} · 用户详情`" @close="detail=null"><dl class="order-detail-list"><div><dt>用户名</dt><dd>{{ detail.username }}</dd></div><div><dt>用户 / 上线 ID</dt><dd>{{ detail.id }} / {{ detail.parentId||'根用户' }}</dd></div><div><dt>邀请码</dt><dd>{{ detail.inviteCode }}</dd></div><div><dt>余额</dt><dd>{{ money(detail.balanceUnits) }} 券</dd></div><div><dt>默认地址</dt><dd>{{ detail.address?`${detail.address.recipient} · ${detail.address.detail}`:'尚未填写' }}</dd></div></dl><h3>直属子市场</h3><ElTable :data="detail.team.markets" empty-text="暂无直属下线"><ElTableColumn prop="name" label="下线"/><ElTableColumn label="累计消费"><template #default="{row}">{{ money(row.units) }} 券</template></ElTableColumn><ElTableColumn label="市场"><template #default="{row}"><ElTag v-if="row.id===detail.team.largestMarketId" type="warning">最大市场</ElTag></template></ElTableColumn></ElTable><h3 class="section-gap">账户流水</h3><ElTable :data="ledger.items"><ElTableColumn prop="title" label="类型"/><ElTableColumn label="变动"><template #default="{row}">{{ money(row.amountUnits) }}</template></ElTableColumn><ElTableColumn prop="createdAt" label="时间" min-width="160"/></ElTable><Pager :page="ledger.page" :total="ledger.total" :disabled="busy" @change="page=>run(async()=>ledger=await api(`/admin/users/${detail.id}/wallet/ledger?page=${page}`))"/><button class="primary full" @click="emit('grant',detail)">为该用户发放产品券</button></Dialog></template>
